'use strict';
const mainPage=document.querySelector('main');
const audiencePage=document.createElement('main');audiencePage.hidden=true;audiencePage.innerHTML='<div class="breadcrumb">Рабочее пространство / Аудитории</div><div class="heading"><div><h1>Аудитории</h1><p>Состав базы и распределение по активности</p></div></div><div class="demo"><b>Демонстрационные данные</b><span>Изменения сохраняются только до обновления страницы. Реальная отправка отключена.</span></div><div id="audience-cards" class="audience-cards"></div><section class="panel"><h2>Как определяется активность</h2><p class="rule-text">Активные — есть переходы за 90 дней. Пассивные — нет переходов, доставлено минимум 3 письма, последнее не менее 7 дней назад. Новые контакты — «Мало данных». Запреты и архив имеют приоритет.</p><p class="muted">События доставки пока не подключены. Импортированные контакты имеют статус «Мало данных»; автоматический расчёт появится позже.</p></section>';document.body.append(audiencePage);
const dialog=document.createElement('dialog');dialog.className='client-dialog';dialog.setAttribute('aria-labelledby','client-title');dialog.innerHTML='<div class="dialog-heading"><div><small>КАРТОЧКА КЛИЕНТА</small><h2 id="client-title"></h2></div><button class="outline" id="close-client" aria-label="Закрыть карточку">✕</button></div><div id="client-content"></div>';document.body.append(dialog);
const localNotes=new Map();let focusedContact=null;
function field(label,value){const box=document.createElement('div');const dt=document.createElement('dt');dt.textContent=label;const dd=document.createElement('dd');dd.textContent=value;box.append(dt,dd);return box;}
function openClient(r){focusedContact=r;const content=document.getElementById('client-content');content.replaceChildren();document.getElementById('client-title').textContent=r.name;const dl=document.createElement('dl');dl.className='client-fields';const pairs=[['Email',r.email||'Не опубликован'],['Аудитории',(r.audiences||[r.audience]).join(', ')],['Активность',r.activity],['Проверка адреса',r.validation],['Источник',r.source],['БИН/ИИН',r.identifier||'Не указан'],['Разрешение на рекламу','Не установлено'],['Публикация адреса',r.publication||'Не установлена'],['Состояние',r.archived?'В архиве':'В рабочей базе']];pairs.forEach(([k,v])=>dl.append(field(k,v)));content.append(dl);const source=document.createElement('section');source.className='client-section';const sh=document.createElement('h3');sh.textContent='Происхождение контакта';const sp=document.createElement('p');sp.textContent=r.source==='Goszakup'?'Пример цепочки: итоги → участник → карточка поставщика → email. Сборщик ещё не подключён.':`Источник: ${r.source}.`;const link=document.createElement('a');link.href=`https://example.com/demo/contact/${r.id}`;link.textContent='Пример ссылки на источник (example.com)';link.target='_blank';link.rel='noopener noreferrer';if(r.evidence?.[0]?.url){link.href=r.evidence[0].url;link.textContent='Открыть источник';source.append(sh,sp,link);}else{source.append(sh,sp);}content.append(source);const metrics=document.createElement('div');metrics.className='stats client-metrics';for(const [label,value]of [['Доставлено',r.delivered],['Открытия пикселя',r.opens],['Переходы',r.clicks]]){const article=document.createElement('article');const span=document.createElement('span');span.textContent=label;const strong=document.createElement('strong');strong.textContent=value;article.append(span,strong);metrics.append(article);}content.append(metrics);const history=document.createElement('section');history.className='client-section';const hh=document.createElement('h3');hh.textContent='История контакта';history.append(hh);const events=[['Добавление в базу',`Источник: ${r.source}`],['Проверка адреса',r.validation]];if(r.delivered)events.push(['Доставка',`${r.delivered} писем принято сервером в демо-отчёте`]);if(r.opens)events.push(['Открытия',`${r.opens} загрузок пикселя; прочтение не подтверждено`]);if(r.clicks)events.push(['Переходы',`${r.clicks} демонстрационных переходов`]);if(r.archived)events.push(['Исключение','Несуществующий адрес: демонстрационный статус']);for(const [title,description]of events){const row=document.createElement('div');row.className='timeline-item';const b=document.createElement('b');b.textContent=title;const p=document.createElement('p');p.textContent=description;row.append(b,p);history.append(row);}content.append(history);const form=document.createElement('form');form.className='client-section';const label=document.createElement('label');label.htmlFor='client-note';label.textContent='Заметки';const textarea=document.createElement('textarea');textarea.id='client-note';textarea.rows=3;textarea.value=r.notes||'';textarea.placeholder='Комментарий о клиенте';const save=document.createElement('button');save.className='outline';save.textContent='Сохранить заметку';const status=document.createElement('p');status.setAttribute('role','status');form.append(label,textarea,save,status);form.addEventListener('submit',async event=>{event.preventDefault();try{await api('/api/contacts/'+r.id+'/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notes:textarea.value})});r.notes=textarea.value;status.textContent='Заметка сохранена в БД.';}catch(error){status.textContent=error.message;}});content.append(form);dialog.showModal();}
document.getElementById('close-client').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
function wireClientRows(){document.querySelectorAll('#rows tr').forEach(tr=>{const checkbox=tr.querySelector('input');const r=data.find(item=>item.id===Number(tr.dataset.contactId));const cell=tr.querySelector('.name');if(!r||cell.querySelector('button'))return;const small=cell.querySelector('small');const button=document.createElement('button');button.className='client-name';button.textContent=r.name;button.addEventListener('click',()=>openClient(r));cell.replaceChildren(button);if(small)cell.append(small);});}
new MutationObserver(wireClientRows).observe(document.getElementById('rows'),{childList:true});wireClientRows();
const navButtons=[...document.querySelectorAll('aside nav button')];const clientsButton=navButtons.find(b=>b.textContent.includes('Клиенты'));const audiencesButton=navButtons.find(b=>b.textContent.includes('Аудитории'));audiencesButton.disabled=false;
function showPage(audiences){mainPage.hidden=audiences;audiencePage.hidden=!audiences;clientsButton.classList.toggle('active',!audiences);audiencesButton.classList.toggle('active',audiences);clientsButton.removeAttribute('aria-current');audiencesButton.removeAttribute('aria-current');(audiences?audiencesButton:clientsButton).setAttribute('aria-current','page');document.title=audiences?'Аудитории — Рассылки':'Клиенты — Рассылки';if(audiences)renderAudiences();}
clientsButton.addEventListener('click',()=>showPage(false));audiencesButton.addEventListener('click',()=>showPage(true));
function renderAudiences(){const container=document.getElementById('audience-cards');container.replaceChildren();for(const root of window.AUDIENCES.filter(a=>!a.parent_id)){const group=window.CONTACT_SUMMARY.audience_counts[String(root.id)]||{total:0,working:0,segments:{}};const section=document.createElement('section');section.className='panel audience-card';const title=document.createElement('h2');title.textContent=root.name;const summary=document.createElement('p');summary.className='muted';summary.textContent=group.total+' контактов · '+group.working+' в рабочей базе';section.append(title,summary);function choose(id,segment=''){document.getElementById('reset').click();document.getElementById('audience').value=String(id);document.getElementById('activity').value=segment;document.getElementById('archive').checked=segment==='Исключены';page=1;loadContactPage();showPage(false);}for(const segment of ['Активные','Пассивные','Мало данных','Исключены']){const button=document.createElement('button');button.className='segment-row';const label=document.createElement('span');label.textContent=segment;const count=document.createElement('b');count.textContent=(group.segments[segment]||0);button.append(label,count);button.onclick=()=>choose(root.id,segment);section.append(button);}const h=document.createElement('h3');h.textContent='Подкатегории';h.style.marginTop='20px';section.append(h);const children=window.AUDIENCES.filter(a=>a.parent_id===root.id);if(!children.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='Подкатегорий пока нет';section.append(empty);}for(const child of children){const button=document.createElement('button');button.className='segment-row';const label=document.createElement('span');label.textContent=child.name;const count=document.createElement('b');count.textContent=(window.CONTACT_SUMMARY.audience_counts[String(child.id)]?.total||0);button.append(label,count);button.onclick=()=>choose(child.id);section.append(button);}container.append(section);}}

